catalog_script_client.script:
function onChange(control, oldValue, newValue, isLoading) {
   if (isLoading || newValue == '') {
      return;
   }

   	var inc = g_form.getValue('inc_date_time');
	var inj = g_form.getValue('inc_date_initial_inj');
	var format = g_user_date_time_format;	
 	var inc_date = getDateFromFormat(inc,format);
	var inj_date = getDateFromFormat(inj, format);

	if (inj_date == 0){
		//No need to perform validation if 'Date of initial injury/illness' is empty
		return;
	}

	//g_form.clearMessages("inc_date_initial_inj");
	//alert(inc_date + "    " + inj_date);
	if(inj_date>inc_date){ //23< 22
		//g_form.setValue('inc_date_initial_inj', '');	
		g_form.setValue('inc_date_time', '');	
		if (g_lang == "en"){
			g_form.showFieldMsg("inc_date_time","'Date and time of the incident' cannot be before 'Date of initial injury/illness'");
		}
		else
		{
			g_form.showFieldMsg("inc_date_time","'Date et heure de l'incident' ne peut pas être avant 'Date de la blessure/maladie initiale'");
		}

		return;
	}

}
